CREATE TABLE IF NOT EXISTS briefs(id TEXT PRIMARY KEY,room TEXT NOT NULL,title TEXT NOT NULL,content TEXT NOT NULL,provenance TEXT NOT NULL,updated TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS actions(id TEXT PRIMARY KEY,owner TEXT NOT NULL,kind TEXT NOT NULL,room TEXT NOT NULL,payload TEXT NOT NULL,digest TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',expires INTEGER NOT NULL,provider_id TEXT,created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,room TEXT NOT NULL,content TEXT NOT NULL,created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO briefs(id,room,title,content,provenance) VALUES('singapore-2026','family','Singapore family trip',
'Travelers: Cyrus, Anhaita, Iyanah, Aarish. SEOUL LAYOVER WINDOWS (Korea local time): Outbound Thu Dec 24 2026 arrival ICN 15:55, departure ICN 23:15, duration 7h20, target airport return 20:15. Return Tue Jan 5 2027 arrival ICN 07:25, departure ICN 17:40, duration 10h15, target airport return 14:40. These are the only Seoul layover windows. The following flight departure/arrival pairs are NOT layovers. Issued flight receipts show: Dec 23 2026 SEA 11:00 -> ICN Dec 24 15:55; ICN Dec 24 23:15 -> SIN Dec 25 05:00. Return Jan 5 2027 SIN 00:10 -> ICN 07:25; ICN 17:40 -> SEA 10:38. All times local to the airport. Two Grand Copthorne Waterfront reservations run Dec 24-Jan 2. Resolve accommodation Jan 2-4 and confirm hotel will hold rooms for early arrival Dec 25. Outbound Seoul layover 7h20; proposed Myeongdong dinner/shopping if immigration and transport permit. Return Seoul layover 10h15; proposed Insadong and Ikseon-dong lunch/cafe. Gyeongbokgung normally closes Tuesdays; Jan 5 is Tuesday. Leave airport only with entry eligibility, onward boarding passes and bags arranged. Recheck entry requirements for Dec 2026 AND Jan 2027, opening hours and train schedules. Aim back at ICN 3 hours before departure; shorten or skip outings if delayed/weather unsafe. SQ608 seat assignments need verification. No live availability, booking modifications or purchases have been performed. Suggestions are proposals, not reservations. Ask each family member for preferences; do not invent preferences or approvals.',
'Cyrus approved family-safe brief publication in this conversation (all five steps). Derived from previously reviewed Oct 20 flight receipts, Aug 15 hotel confirmations and proposed Seoul itinerary. Booking references, payments, passports and private email contents excluded.')
ON CONFLICT(id) DO UPDATE SET content=excluded.content,provenance=excluded.provenance,updated=CURRENT_TIMESTAMP;
